import { Box } from "@/shared/ui/layout/Box";
import { Text } from "@/shared/ui/typography/Text";

export function StreamChip({
  label,
  tone,
  count,
  active,
  onClick,
}: {
  label: string;
  tone: string;
  count: number;
  active: boolean;
  onClick: () => void;
}) {
  return (
    <button
      onClick={onClick}
      className="mono"
      style={{
        display: "inline-flex",
        alignItems: "center",
        gap: 6,
        cursor: "pointer",
        padding: "3px 9px",
        borderRadius: 99,
        fontSize: 10.5,
        color: active ? "var(--fg)" : "var(--fg-muted)",
        background: active ? `color-mix(in oklch, ${tone}, transparent 84%)` : "var(--bg-panel)",
        border: `1px solid ${active ? tone : "var(--border-soft)"}`,
      }}
    >
      <Box as="span" bg={tone} radius={99} style={{ width: 7, height: 7 }} />
      {label}
      <Text as="span" mono size={9.5} tone="dim">{count}</Text>
    </button>
  );
}
